insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('JE', 'default', 'Jersey reference chart of accounts', '{}'::jsonb, true, 'companies', array['JE-FRS102-1A-BS', 'JE-FRS102-1A-IS']::text[], null, 'There is no legal chart of accounts in Jersey. The Companies (Jersey) Law 1991 requires a company to keep accounting records sufficient to show and explain its transactions and to disclose its financial position with reasonable accuracy, to preserve them for at least ten years from the date they are made, and to have its directors prepare accounts in accordance with generally accepted accounting principles that the accounts state (Walkers, consulted 2026-10-10; the text of the Law itself was not opened, see the README). The Law prescribes no chart and no format. This chart is original and follows British bookkeeping practice, because the principles most Jersey companies declare are UK GAAP (FRS 102), with IFRS the other common choice: four digits, blocked so that each range reaches one line of the balance sheet and the profit and loss account of FRS 102 Section 1A (small entities) in the layout statements.json carries. It has no United Kingdom value added tax, PAYE or CIS account, because Jersey is outside the United Kingdom VAT system; it carries the accounts of the Jersey goods and services tax instead: input tax (1140), output tax (2210), import GST owed to Customs (2215), and the two settlement accounts a filed return clears (2230 payable, 1145 refundable), which are the only accounts besides trade debtors and creditors that can be reconciled.', 'je-companies-walkers')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

