insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('JE', 'JE-P-BL', 'Purchase, GST 5 %, input tax not recoverable', '{}'::jsonb, 'A purchase whose input tax the business cannot credit, for instance because it makes exempt supplies', 'percent', 5, 'purchase', 'domestic', date '2011-06-01', null, 'Goods and Services Tax (Jersey) Law 2007, art. 33 and 34 (input tax credited against output tax) and the partial exemption rules for a business that also makes exempt supplies (Revenue Jersey, partial exemption booklet: the PDF could not be read as text, see the README). The GST lands on the cost; no box takes it. Box 4 takes the value.', null, null, 110, 'gst', false, array['supply_nature']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-P-ES', 'Purchase, exempt', '{}'::jsonb, 'A purchase of an exempt supply', 'percent', 0, 'purchase', 'exempt', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 5: an exempt supply carries no GST and gives no credit. Box 4 takes the value, which is a business cost from a Jersey supplier.', null, null, 130, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-P-IMP', 'Import of goods, GST 5 % paid to Customs', '{}'::jsonb, 'Goods imported into Jersey, the GST paid to Customs at the border', 'percent', 5, 'purchase', 'import', date '2011-06-01', null, 'Revenue Jersey, Supplying goods and services from outside Jersey (consulted 2026-10-10): goods imported into Jersey are subject to GST; a GST-registered importer that pays at the border recovers it as input tax. Box 5 takes the value of the imports without GST and box 7 the GST paid. The supplier is owed the value alone: the GST is owed to Customs and waits on 2215 until it is paid.', null, null, 150, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-place-of-supply', null, null, null, null),
  ('JE', 'JE-P-IMP-DEF', 'Import of goods, GST deferred by an approved customs trader', '{}'::jsonb, 'Goods imported by a GST-registered importer approved as a customs trader, GST accounted for on the return', 'percent', 5, 'purchase', 'import', date '2011-06-01', null, 'Revenue Jersey, Supplying goods and services from outside Jersey (consulted 2026-10-10): a GST-registered importer approved as a customs trader can defer payment; it excludes the GST at import and includes the goods'' value in box 5 of the return instead. The page does not say how the tax is shown in boxes 6 and 7; this code assumes the importer accounts for the GST as output tax (box 6) and claims it as input tax (box 7) in the same return, so the net is nil. A point for Revenue Jersey to confirm: see the README.', null, null, 160, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-place-of-supply', null, null, null, null),
  ('JE', 'JE-P-NR', 'Purchase with no GST — supplier not registered', '{}'::jsonb, 'A purchase from a supplier that does not charge GST', 'percent', 0, 'purchase', 'not_subject', date '2008-05-06', null, 'A business below the registration threshold of £300,000 of taxable supplies in twelve months need not register (Revenue Jersey, GST registration thresholds, consulted 2026-10-10) and charges no GST. Box 4 takes the value; there is no input tax.', null, null, 140, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-registration', null, null, null, null),
  ('JE', 'JE-P-RC', 'Service from abroad, reverse charge, GST 5 %, recoverable', '{}'::jsonb, 'A service supplied by a person belonging outside Jersey and received in Jersey', 'percent', 5, 'purchase', 'foreign_services_received', date '2008-05-06', null, 'Revenue Jersey, Supplying goods and services from outside Jersey (consulted 2026-10-10): a service can be supplied in Jersey even when supplied by someone belonging outside Jersey, and the Jersey customer receiving certain services from abroad self-assesses the GST by including the value in box 5 of the return. Same assumption on boxes 6 and 7 as JE-P-IMP-DEF.', null, null, 170, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'je-gst-place-of-supply', null, null, null, null),
  ('JE', 'JE-P-TX', 'Purchase, standard-rated, GST 5 %', '{}'::jsonb, 'A purchase with GST charged by a GST-registered supplier in Jersey', 'percent', 5, 'purchase', 'domestic', date '2011-06-01', null, 'Goods and Services Tax (Jersey) Law 2007, art. 8(1): ''GST shall be charged at the rate of 5%'' (jerseylaw.je, consulted 2026-10-10). Revenue Jersey, GST taxed on goods and services: standard rate 5 %, applied to most goods and services, and no reduced rate. Input tax is the GST charged on goods and services used in the business; the law credits it against the output tax of the period and the excess is refundable as a GST credit (art. 33 and 34, as read in the part of the Law that was opened). Box 4 takes the value, box 7 the GST.', null, null, 100, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-P-ZR', 'Purchase, zero-rated', '{}'::jsonb, 'A purchase of zero-rated goods or services from a Jersey supplier', 'percent', 0, 'purchase', 'domestic', date '2008-05-06', null, 'Revenue Jersey, GST taxed on goods and services (consulted 2026-10-10): zero-rated supplies are taxed at 0 %. Box 4 takes the value.', null, null, 120, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-taxed', null, null, null, null),
  ('JE', 'JE-S-ES', 'Exempt supply', '{}'::jsonb, 'An exempt supply listed in Schedule 5: finance, insurance, postal services, medical and paramedical supplies, supplies by charities, child care, education, burial and cremation', 'percent', 0, 'sale', 'exempt', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 5, Groups 1 to 8: finance, insurance, postal services, medical and paramedical supplies, supplies by charities, child care, education, burial and cremation (jerseylaw.je, consulted 2026-10-10; the conditions of each Group were not read in full). An exempt supply carries no GST, is not a taxable supply and is in no box of the return; the input tax on what went into it is restricted by the partial exemption rules, which the pack does not compute. No exemption reason code: the VATEX list names articles of the European Union VAT Directive, which does not bind a Jersey supplier.', 'E', null, 80, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-S-NS', 'Sale outside the scope of GST', '{}'::jsonb, 'A supply made outside Jersey by a Jersey business, or one that is not a supply for GST', 'percent', 0, 'sale', 'not_subject', date '2008-05-06', null, 'Revenue Jersey, Supplying goods and services from outside Jersey (consulted 2026-10-10) says a service can be supplied in Jersey even when the supplier belongs outside it; a supply whose place is outside Jersey is outside the scope of Jersey GST and is in no box. The United Kingdom''s VAT does not apply to a sale between Jersey and the United Kingdom, Jersey being outside the UK VAT system.', 'O', null, 90, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-place-of-supply', null, null, null, null),
  ('JE', 'JE-S-SR', 'Sale, standard-rated, GST 5 %', '{}'::jsonb, 'A taxable supply made in Jersey', 'percent', 5, 'sale', 'domestic', date '2011-06-01', null, 'Goods and Services Tax (Jersey) Law 2007, art. 8(1): ''GST shall be charged at the rate of 5%'' (jerseylaw.je, consulted 2026-10-10). Revenue Jersey, GST taxed on goods and services: standard rate 5 %, applied to most goods and services, and no reduced rate. The GST charged on the sale is output tax: box 6 of the GST return, and the value without GST is in box 1.', 'S', null, 10, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-S-SR-INC', 'Retail sale, standard-rated, GST 5 %, the price includes the GST', '{}'::jsonb, 'A taxable retail supply whose displayed price includes the GST', 'percent', 5, 'sale', 'domestic', date '2011-06-01', null, 'Goods and Services Tax (Jersey) Law 2007, art. 8(1): ''GST shall be charged at the rate of 5%'' (jerseylaw.je, consulted 2026-10-10). Revenue Jersey, GST taxed on goods and services: standard rate 5 %, applied to most goods and services, and no reduced rate. A price that includes the GST is the way a shop shows it; the engine takes the GST out of the gross. The simplified invoice Revenue Jersey allows for a retail sale up to £250 states the gross amount and the rate (Keeping records and accounts for GST, consulted 2026-10-10).', 'S', null, 20, 'gst', true, '{}'::tax_condition[], null, true, false, null, 'je-gst-records', null, null, null, null),
  ('JE', 'JE-S-ZR-DW', 'Supply of a dwelling, zero-rated', '{}'::jsonb, 'The supply of a dwelling, and the other zero-rated supplies of land', 'percent', 0, 'sale', 'domestic', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 6 (''Supply of dwelling, and zero-rated supplies of land, services or material''; jerseylaw.je, consulted 2026-10-10) and Revenue Jersey, GST taxed on goods and services: housing is zero-rated. Which supplies of land fall in the Part is a classification the ledger cannot see; the wording of the Part was not read in full.', 'Z', null, 60, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-S-ZR-EXP', 'Export of goods, zero-rated', '{}'::jsonb, 'An export of goods from Jersey', 'percent', 0, 'sale', 'export', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 6 (''Zero-rating of exports''; jerseylaw.je, consulted 2026-10-10), and Revenue Jersey, GST taxed on goods and services: exports of goods are zero-rated. The sale is a taxable supply at 0 %: box 1 and box 2 of the return both take its value, so that box 3 (sales subject to GST) leaves it out. The supplier must hold evidence that the goods left Jersey.', 'G', null, 30, 'gst', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-S-ZR-INTL', 'International service, zero-rated', '{}'::jsonb, 'A service supplied under a contract with a person who belongs outside Jersey and benefits a person who belongs outside Jersey', 'percent', 0, 'sale', 'export', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 6, paragraph 5 (''Supply of international services zero-rated''; the paragraph''s wording was not read in full, see the README): services supplied to a person who belongs outside Jersey and that benefit a person who belongs outside Jersey are zero-rated, with those relating to land or goods situated in Jersey left out (Revenue Jersey, GST taxed on goods and services, consulted 2026-10-10: ''international services''). Boxes 1 and 2.', 'G', null, 40, 'gst', true, array['supply_nature', 'buyer_status']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null),
  ('JE', 'JE-S-ZR-ISE', 'Remitted supply to an International Services Entity, zero-rated', '{}'::jsonb, 'A supply to an approved International Services Entity for the purpose of its business, on the entity''s end user relief certificate', 'percent', 0, 'sale', 'domestic', date '2008-05-06', null, 'Revenue Jersey, GST on goods and services supplied to an ISE (consulted 2026-10-10): supplies to an approved ISE for the purpose of a business carried on through it are ''remitted supplies'', treated as zero-rated for the return and shown in box 2 with the value of zero-rated supplies; the page tells the supplier to use the GST code used for zero-rated sales such as exports. A retailer may charge GST on an individual sale to an ISE under £1,000, which the ISE reclaims. The ISE regime itself (annual fee instead of GST) is not in this pack: see the README.', 'Z', null, 50, 'gst', true, array['buyer_certificate']::tax_condition[], null, false, false, null, 'je-gst-ise-supplies', null, null, null, null),
  ('JE', 'JE-S-ZR-RX', 'Medicine on prescription, zero-rated', '{}'::jsonb, 'A medicine supplied on prescription', 'percent', 0, 'sale', 'domestic', date '2008-05-06', null, 'Goods and Services Tax (Jersey) Law 2007, Schedule 6 (''Zero-rating of medicines on prescription''; jerseylaw.je, consulted 2026-10-10) and Revenue Jersey, GST taxed on goods and services: ''medical prescriptions'' are zero-rated.', 'Z', null, 70, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'je-gst-law', null, null, null, null)
