insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('JE', 'JE-GST', 'GST return (Revenue Jersey)', array['quarter']::declaration_period[], 'quarter'::declaration_period, date '2008-05-06', null, 'Revenue Jersey, Submit your GST return and GST registration thresholds (consulted 2026-10-10): GST returns are quarterly (January to March, April to June, July to September, October to December) unless the registration letter says otherwise, and are completed online with the business''s Tax Identification Number and GST reference. The return has eight boxes, not the nine of the United Kingdom VAT return. Monthly returns and other cadences the registration letter may set are not declared: no page opened says so.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10): ''Your return is due for submission no later than the last day of the month following the return period'', so 30 April for January to March; the registration page adds that payment is due within one month of quarter-end. Penalties and surcharges for late filing are not modelled.', 'je-gst-return', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('JE', 'JE-GST', '1', 'base', 'Total sales excluding GST', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 1 — the net value of all taxable sales, zero-rated sales included; exempt supplies are not taxable supplies and are left out. Credit notes reduce it.', 'je-gst-return'),
  ('JE', 'JE-GST', '2', 'base', 'Zero-rated and remitted sales', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 2 — zero-rated sales and the remitted supplies to International Services Entities, included in box 1. Exports, international services, dwellings, prescription medicines and ISE supplies.', 'je-gst-return'),
  ('JE', 'JE-GST', '3', 'total', 'Total sales subject to GST', '{}'::jsonb, 30, null, array['1']::text[], array['2']::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 3 — calculated by the form: box 1 less box 2.', 'je-gst-return'),
  ('JE', 'JE-GST', '4', 'base', 'Purchases and expenses excluding imports', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 4 — business costs from Jersey suppliers, without GST. The pack carries every purchase from a Jersey supplier here, taxed, zero-rated, exempt, with GST not recoverable or with no GST; the page does not say whether exempt or untaxed costs belong in it, which is a point to confirm (see the README).', 'je-gst-return'),
  ('JE', 'JE-GST', '5', 'base', 'Total value of imports', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 5 — all imports without GST: goods, and certain services received from outside Jersey that the customer self-assesses (Supplying goods and services from outside Jersey, consulted 2026-10-10).', 'je-gst-return'),
  ('JE', 'JE-GST', '6', 'tax', 'GST on sales', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 6 — the output tax charged to customers, net of credit notes, and the GST the pack self-assesses on deferred imports and reverse-charged services.', 'je-gst-return'),
  ('JE', 'JE-GST', '7', 'tax', 'GST on purchases', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 7 — the deductible input tax: GST on domestic purchases, GST paid to Customs on imports, and the self-assessed GST of box 6 on deferred imports and reverse-charged services, net of credit notes.', 'je-gst-return'),
  ('JE', 'JE-GST', '8', 'total', 'Amount payable or refundable', '{}'::jsonb, 80, null, array['6']::text[], array['7']::text[], null, null, false, false, null, 'Revenue Jersey, Submit your GST return (consulted 2026-10-10), box 8 — calculated by the form: box 6 less box 7; a negative amount is a refund. The GST (Jersey) Law 2007, art. 34, credits input tax against output tax and refunds the excess as a GST credit.', 'je-gst-return')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('JE-FRS102-1A-BS', 'JE', 'default', 'Balance sheet — FRS 102 Section 1A, Format 1', 'balance_sheet', 'UK-FRS102', date '1970-01-01', null, 'FRS 102 The Financial Reporting Standard applicable in the UK and Republic of Ireland, Section 1A (Small Entities), is the framework this statement follows: the Companies (Jersey) Law 1991 requires accounts that give a true and fair view where an audit is required and that state the generally accepted accounting principles adopted (Walkers, consulted 2026-10-10), and the Law does not define ''accounts'' or set their format; UK GAAP is one of the principles a Jersey company may declare. The layout is the one Section 1A shows for small entities, the Format 1 balance sheet (fixed assets, current assets, creditors due within and after one year, provisions, capital and reserves) in its summarised form. It is a layout borrowed from the United Kingdom standard, not a format Jersey law imposes, and the lines are the pack''s own groupings of its original chart. GST accounts sit in debtors (1140, 1145) and in other creditors (2210, 2215, 2230). Line K.IV carries the year''s result not yet closed to retained earnings, so that the statement ties to the cent on an open year. The text of the Law itself could not be opened; see the README.', 'frs-102'),
  ('JE-FRS102-1A-IS', 'JE', 'default', 'Profit and loss account — FRS 102 Section 1A, Format 1', 'income_statement', 'UK-FRS102', date '1970-01-01', null, 'FRS 102 Section 1A (Small Entities): the profit and loss account in the Format 1 layout (turnover, cost of sales, gross profit, distribution costs, administrative expenses, other operating income, investment income, interest, tax). Jersey law requires accounts that give a true and fair view and names no format (Companies (Jersey) Law 1991, per Walkers, consulted 2026-10-10); the layout is borrowed from the United Kingdom standard. The tax line carries Jersey income tax on the company''s profit (0 % as standard, 10 % for financial services companies, 20 % for utility companies and for Jersey property income and development, up to 20 % for large retailers, Government of Jersey, Moving to Jersey: money and tax, consulted 2026-10-10), booked by the company: nothing in this pack computes it.', 'frs-102')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

