update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Revenue Jersey, Keeping records and accounts for GST (consulted 2026-10-10): a GST invoice carries an individual serial number. The page asks that each invoice be identified and does not say the series may have no gap, so the style is `sequential` and not a gapless one; the pattern in number_format is one a business may choose.',
  numbering_source_key          = 'je-gst-records',
  payment_terms_legal_reference = 'No Jersey statute was found that sets a payment term between two businesses in the absence of an agreement, or a rate of interest on a commercial debt paid late; the Late Payment of Commercial Debts (Interest) Act 1998 is a United Kingdom statute and no source consulted says it extends to Jersey. `legal_payment_days` and `late_payment_reference` are therefore empty. This is an absence of a source found, not a proof of absence: a Jersey lawyer should confirm it.',
  payment_terms_source_key      = 'je-gst-records',
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'The invoice carries a ''tax point date (the date on which the transaction took place)'' and a date of issue where it differs (Revenue Jersey, Keeping records and accounts for GST, consulted 2026-10-10). The rule that fixes the tax point of a supply in the Goods and Services Tax (Jersey) Law 2007 was not read in the part of the Law that was opened, so `invoice_date` is declared as the common convention and not as a rule read from the text; see the README.',
  tax_point_source_key          = 'je-gst-records',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Jersey statute or Revenue Jersey page was found that obliges a business to issue or accept an electronic invoice (Revenue Jersey, Keeping records and accounts for GST, consulted 2026-10-10: it asks for tax invoices and six years of records and says nothing of an electronic format), and no Peppol Authority is listed for Jersey as far as the author knows (not re-checked against the OpenPeppol list). `profile`, `party_scheme` and `vat_scheme` are null: there is no domestic profile to name, and Jersey is outside the European Union and United Kingdom VAT systems.',
  einvoice_source_key           = 'je-gst-records',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'JE';

