values
  ('JE', 'tax_invoice', 'always', 'Tax invoice', '{}'::jsonb, 10, date '1970-01-01', null, 'Revenue Jersey, Keeping records and accounts for GST (consulted 2026-10-10): a GST invoice carries the words ''tax invoice'' in a prominent place, together with the supplier''s name, address and GST registration number, the tax point date, a serial number, a description, the selling price, the GST charged, the price including GST and an indication whether GST is chargeable.'),
  ('JE', 'zero_rated', 'export', 'Zero-rated supply: GST is chargeable at 0 %.', '{}'::jsonb, 20, date '1970-01-01', null, 'Revenue Jersey, Keeping records and accounts for GST (consulted 2026-10-10): the invoice indicates whether GST is chargeable on the supply; Goods and Services Tax (Jersey) Law 2007, Schedule 6, zero-rates exports of goods and international services.'),
  ('JE', 'exempt', 'exempt', 'Exempt supply: GST is not chargeable.', '{}'::jsonb, 30, date '1970-01-01', null, 'Revenue Jersey, Keeping records and accounts for GST (consulted 2026-10-10): the invoice indicates whether GST is chargeable on the supply; Goods and Services Tax (Jersey) Law 2007, Schedule 5, lists the exempt supplies.')
